def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([1, 2]), fmt([3, 3, 3]), fmt([9, 7, 5, 3]), fmt([2, 5, 3, 4, 1, 6]),
             fmt([4, 4, 4, 2, 4]), fmt([1, 1, 2, 1, 2, 1, 3]), fmt([1, 100000, 1, 100000, 99999, 100000])]
    for n in (3, 4, 5, 6, 8, 10, 15, 25, 40):
        for hi in (4, 30):
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(1, N) for _ in range(N)]))
    tests.append(fmt(sorted(rng.randint(1, N) for _ in range(N))))
    tests.append(fmt([N] * N))
    noisy = [N - i for i in range(N)]
    for _ in range(300):
        p = rng.randrange(N)
        noisy[p] = rng.randint(1, N)
    tests.append(fmt(noisy))
    tests.append(fmt([rng.randint(N // 2, N) for _ in range(N)]))
    tests.append(fmt([N - i for i in range(N)]))
    return tests
